code.VEML7700 \u00b7 0x10:
// VEML7700 ambient light (I2C 0x10) on the sensor header.
#include <Wire.h>
#define VEML7700 0x10

void light_init() {                 // gain x1, 100 ms, enabled
  Wire.beginTransmission(VEML7700);
  Wire.write(0x00); Wire.write(0x00); Wire.write(0x00);
  Wire.endTransmission();
}
float light_lux() {
  Wire.beginTransmission(VEML7700); Wire.write(0x04);
  Wire.endTransmission(false);
  Wire.requestFrom(VEML7700, 2);
  uint16_t raw = Wire.read() | (Wire.read() << 8);
  return raw * 0.0576f;              // gain x1 @ 100 ms
}

