code.rs485:
// RS485 · Modbus RTU probe — read holding register 0 of slave 1.
// Uses the pure core canary/io/modbus_rtu.h (CRC + framing).
#include <Arduino.h>
#include "canary/io/modbus_rtu.h"
namespace mb = canary::io::modbus;

void rs485_probe() {
  Serial1.begin(9600, SERIAL_8N1, RS485_PIN_RX, RS485_PIN_TX);
  uint8_t req[8];
  size_t n = mb::build_read_holding(1, 0, 1, req, sizeof(req));
  Serial1.write(req, n); Serial1.flush();          // A/B, auto-dir
  uint8_t resp[16]; size_t got = 0;
  uint32_t deadline = millis() + 300;
  while (got < 7 && (int32_t)(deadline - millis()) > 0)
    while (Serial1.available()) resp[got++] = Serial1.read();
  uint16_t reg[1];
  if (mb::parse_registers(resp, got, 1, mb::FN_READ_HOLDING, reg, 1) == 1)
    Serial.printf("slave 1 reg0 = %u\n", reg[0]);
}

code.can:
// CAN · TWAI — send one test frame; received frames are drained.
// Uses the pure core canary/io/can_frame.h + ESP-IDF TWAI.
#include <driver/twai.h>

void can_begin() {
  auto g = TWAI_GENERAL_CONFIG_DEFAULT((gpio_num_t)CAN_PIN_TX,
                                       (gpio_num_t)CAN_PIN_RX, TWAI_MODE_NORMAL);
  auto t = TWAI_TIMING_CONFIG_500KBITS();
  auto f = TWAI_FILTER_CONFIG_ACCEPT_ALL();
  twai_driver_install(&g, &t, &f); twai_start();   // H/L, 500 kbit/s
}
void can_send() {
  twai_message_t m = {};
  m.identifier = 0x100; m.data_length_code = 8;
  for (int i = 0; i < 8; i++) m.data[i] = 0xC0 + i;
  twai_transmit(&m, pdMS_TO_TICKS(50));
}

